public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.round(n * 0.05);
    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);
    double sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (n - 2 * k);
}

