public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] sum = new int[n / 2];
    for (int i = 0; i < n; i++) {
        sum[i / 2] += arr[i];
    }
    for (int i = 0; i < n / 2; i++) {
        if (sum[i] % k != 0) {
            return false;
        }
    }
    return true;
}
