public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a priority queue to store the nodes to visit
    PriorityQueue<Node> queue = new PriorityQueue<>();

    // Add node 0 to the queue with a priority of 0
    queue.add(new Node(0, 0));

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    while (!queue.isEmpty()) {
        // Get the node with the highest priority from the queue
        Node current = queue.poll();

        // If the current node has not been visited before, mark it as visited and add its neighbors to the queue
        if (!visited[current.node]) {
            visited[current.node] = true;
            for (int neighbor : graph.neighbors(current.node)) {
                if (!visited[neighbor]) {
                    queue.add(new Node(neighbor, current.priority + 1));
                }
            }
        }

        // If the current node has an apple, update the minimum time required to collect all apples and return to node 0
        if (hasApple[current.node]) {
            minTime = Math.max(minTime, current.priority + 1);
        }
    }

    return minTime;
}

