public int maxUniqueSplit(String s) {
    int max = 0;
    for (int i = 1; i < s.length(); i++) {
        String left = s.substring(0, i);
        String right = s.substring(i);
        if (left.length() > 0 && right.length() > 0 && !left.equals(right)) {
            max = Math.max(max, 1 + maxUniqueSplit(left) + maxUniqueSplit(right));
        }
    }
    return max;
}
```
