private static boolean isSteppingNumber(int num) {
    int prevDigit = num % 10;
    while (num > 0) {
        int digit = num % 10;
        if (Math.abs(digit - prevDigit) != 1) {
            return false;
        }
        prevDigit = digit;
        num /= 10;
    }
    return true;
