public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int m = mat[0].length;
    int[] result = new int[n * m];
    int row = 0;
    int col = 0;
    int index = 0;
    while (row < n && col < m) {
        result[index++] = mat[row][col];
        if ((row + col) % 2 == 0) {
            if (col == m - 1) {
                row++;
            } else {
                col++;
            }
        } else {
            if (row == n - 1) {
                col++;
            } else {
                row++;
            }
        }
    }
    return result;
}
