    int factor2 = 2, factor3 = 3, factor5 = 5;
    for (int i = 1; i < n; i++) {
        int min = Math.min(Math.min(factor2, factor3), factor5);
        uglyNumbers[i] = min;
        if (min == factor2) {
            i2++;
            factor2 = uglyNumbers[i2] * 2;
        }
        if (min == factor3) {
            i3++;
            factor3 = uglyNumbers[i3] * 3;
        }
        if (min == factor5) {
            i5++;
            factor5 = uglyNumbers[i5] * 5;
        }
    }
    return uglyNumbers[n - 1];
}
